def sortColors(nums):
    a = list(nums)
    lo, i, hi = 0, 0, len(a) - 1
    while i <= hi:
        if a[i] == 0:
            a[lo], a[i] = a[i], a[lo]
            lo += 1
            i += 1
        elif a[i] == 2:
            a[hi], a[i] = a[i], a[hi]
            hi -= 1
        else:
            i += 1
    return a
